/**
 * Создание строки фильтров с датами и выбором отображения
 */
function createProjectFilterRow(frm, $wrapper) {
    let controls = $('<div class="projects-workload-controls unified-filters-row"></div>').appendTo($wrapper);

    let filtersContainer = $('<div class="filters-container"></div>').appendTo(controls);

    // Гарантируем, что даты инициализированы
    ensureDatesInitialized();

    // Дропдаун типа отображения (дни/недели/месяцы)
    const viewTypeControl = createViewTypeDropdown(filtersContainer);

    // НОВОЕ: Дропдаун периода отображения (квартал/полгода/год)
    const periodRangeControl = createPeriodRangeDropdown(filtersContainer);

    // Разделитель
    $('<div class="filter-separator"></div>').appendTo(filtersContainer);

    // Кнопки
    let buttonsContainer = $('<div class="filter-buttons"></div>').appendTo(filtersContainer);

    // Кнопка обновления
    let refreshBtn = $(`
        <button class="btn btn-default btn-sm" title="${__('Refresh Data')}">
            ↻
        </button>
    `).appendTo(buttonsContainer);

    refreshBtn.on('click', function() {
        if (WL_DEBUG) console.log('Manual refresh triggered');

        // Очищаем кэш
        projectWorkloadCache = {
            globalCache: {}
        };

        // Сбрасываем метаданные
        window.projectWorkloadMetadata = {};

        // также очищаем индекс
        window.projectWorkloadIndexed = null;

        // Загружаем данные с принудительным обновлением
        debouncedLoadProjectWorkloadData(frm, true, true);
    });

    return controls;
}

// ========== ОСНОВНЫЕ ФУНКЦИИ ЗАГРУЗКИ ==========

/**
 * Загрузка данных таблицы
 */
async function load_project_workload_data(frm, forceRefresh = false) {
    if (WL_DEBUG) console.log('>>> load_project_workload_data STARTED (3-level)', {
        isProjectWorkloadLoading,
        forceRefresh,
        hasDT: !!frm.project_workload_dt
    });

    if (isProjectWorkloadLoading) {
        if (WL_DEBUG) console.log('Project workload data is already loading, skipping duplicate call');
        return;
    }

    const timer = startTimer('load_project_workload_data');
    let wrapper = frm.get_field("custom_workload");
    let $wrapper = wrapper?.$wrapper;

    window._pw_cache = { availableHours: {} };

    try {
        isProjectWorkloadLoading = true;
        if (WL_DEBUG) console.log('START loading project workload data with view type:', currentViewType);

        ensureDatesInitialized();
        syncPwrProjectGlobals();

        if (WL_DEBUG) console.log(`Loading data for period: ${displayDateFrom} to ${displayDateTo}`);


        if (frm.project_workload_dt) {
            frm.project_workload_dt.freeze();
        }

        const result = await get_project_workload_data(frm, forceRefresh);
        const table_data = result.tree_data;
        const server_periods = result.periods;

        projectWorkloadTableData = table_data;
        frm.project_workload_periods = server_periods || [];

        if (frm.project_workload_dt) {
            const periods = server_periods;
            if (WL_DEBUG) console.log(`Using ${periods.length} periods for ${currentViewType} view`);
            if (WL_DEBUG) console.log(`Table data has ${table_data.length} rows with levels:`, 
                table_data.map(r => ({level: r.level, name: r.participant})).slice(0, 10));

            const columns = get_project_workload_columns_definition(periods);

             $wrapper?.addClass("animate");
            frm.project_workload_dt.refresh(table_data, columns);

            // Сворачиваем все узлы (показываем только пользователей)
            if (frm.project_workload_dt.rowmanager) {
                frm.project_workload_dt.rowmanager.collapseAllNodes();
            }

            frm.project_workload_dt.unfreeze();

            setupTaskDoubleClickHandler();
            requestProjectWorkloadChartReload(frm);
        }
    } catch (error) {
        console.error('Error loading project workload data:', error);
        if (frm.project_workload_dt) {
            frm.project_workload_dt.unfreeze();
        }
    } finally {
        isProjectWorkloadLoading = false;
        endTimer(timer);
        if (WL_DEBUG) console.log('END loading project workload data');

        let active_tab = frm.get_active_tab();
        let fieldname = active_tab?.df.fieldname;

        if (fieldname === 'custom_загрузка') {
            setTimeout(() => {
                $wrapper?.removeClass("animate")},
                1000 );
        }
    }
}

let projectTabChangeHandler = null;
/**
 * Отрисовка таблицы загрузки проекта
 */
async function render_project_workload_table(frm) {
    if (WL_DEBUG) console.log('render_project_workload_table CALLED');
    if (WL_DEBUG) console.log('Table initialized flag:', frm.project_workload_table_initialized);

    const timer = startTimer('render_project_workload_table');
    let wrapper = frm.get_field("custom_workload");
    if (!wrapper) {
        if (WL_DEBUG) console.log('Wrapper not found!');
        endTimer(timer);
        return;
    }

    let $wrapper = wrapper.$wrapper;
    if (!$wrapper || !$wrapper.length) {
        if (WL_DEBUG) console.log('$wrapper not found or empty!');
        endTimer(timer);
        return;
    }

    $wrapper.addClass("project_workload_container");

    // Если таблица уже инициализирована - не создаем заново
    if (frm.project_workload_table_initialized) {
        applyProjectWorkloadSectionLayout(frm);
        requestProjectWorkloadChartReload(frm);
        if (WL_DEBUG) console.log('Table already initialized - skipping creation');
        endTimer(timer);
        return;
    }

    if (WL_DEBUG) console.log('CREATING NEW TABLE...');

    try {
        await ensureProjectWorkloadAgGrid();
    } catch (error) {
        console.error('Error loading ProjectsWorkloadAgGrid:', error);
        frappe.msgprint(__('Could not load table component: {0}', [error.message]));
        endTimer(timer);
        return;
    }

    // Очищаем контейнер
    $wrapper.empty();

    // Создаем строку фильтров
    let controls = createProjectFilterRow(frm, $wrapper);

    // Контейнер для таблицы
    let table_container = $('<div class="project-workload-table"></div>').appendTo($wrapper);

    // Инициализация таблицы
    if (WL_DEBUG) console.log('Initializing ProjectsWorkloadAgGrid...');

    frm.project_workload_dt = new ProjectsWorkloadAgGrid.Table(table_container[0], {
        columns: [],
        data: [],
        rowHeight: 40,
        headerHeight: 70,
        participantWidth: 250,
        indentSize: 18,
        extraClass: "project-workload-ag-grid",
        freezeMessage: __("Loading data..."),
        isRowExpandable: function(row) {
            if (!row || row.expandable !== true) {
                return false;
            }
            return this.rowHasTreeChildren(row);
        },
        onCellDoubleClick: handleProjectWorkloadCellDoubleClick
    });

    if (WL_DEBUG) console.log('ProjectsWorkloadAgGrid created');

    applyProjectWorkloadSectionLayout(frm);
    setTimeout(() => applyProjectWorkloadSectionLayout(frm), 0);

    // Обновляем значения в контролах дат
    ensureDatesInitialized();
    updateDateControls();

    // Загружаем данные и ТОЛЬКО ПОСЛЕ УСПЕХА устанавливаем флаг
    if (WL_DEBUG) console.log('Loading initial data...');
    load_project_workload_data(frm, false).then(() => {
        lastLoadedProject = frm.doc.name;
        lastLoadedTime = new Date();

        // Устанавливаем флаг ТОЛЬКО после успешной загрузки
        frm.project_workload_table_initialized = true;
        if (WL_DEBUG) console.log('Table initialized flag set to TRUE after successful load');
        requestProjectWorkloadChartReload(frm);

        endTimer(timer);
        if (WL_DEBUG) console.log('Initial data loaded successfully');
    }).catch((error) => {
        console.error('Initial data load failed:', error);
        // При ошибке НЕ устанавливаем флаг, чтобы можно было повторить попытку
        endTimer(timer);
    });

    if ( projectTabChangeHandler ) {
        $('.nav-link[data-toggle="tab"]').off('shown.bs.tab', projectTabChangeHandler );
        projectTabChangeHandler = null;
    }

    projectTabChangeHandler = function (e) {
        let tab_fieldname = $(e.target).attr("data-fieldname");
        if (WL_DEBUG) console.log('Переключено на вкладку:', tab_fieldname);  // Для отладки

        if (tab_fieldname === 'custom_загрузка') {
            applyProjectWorkloadSectionLayout(frm);
            requestProjectWorkloadChartReload(frm);
            setTimeout(() => {
                $wrapper?.removeClass("animate")},
                1000 );
        } else {
            setTimeout(() => {
                $wrapper?.addClass("animate")},
                1000 );
        }
    };

    $('.nav-link[data-toggle="tab"]').on('shown.bs.tab', projectTabChangeHandler );
}

// ========== КЛИЕНТСКИЙ СКРИПТ ==========

frappe.ui.form.on("Project", {    
    onload: function(frm) {
        if (WL_DEBUG) console.log("Project Workload: onload");

        // Сброс всех переменных
        projectWorkloadCache = { globalCache: {} };
        projectWorkloadTableData = [];
        window.projectWorkloadMetadata = {};
        isRedrawingGantt = false;
        isProjectWorkloadLoading = false;
        currentViewType = 'daily';
        window.currentViewType = currentViewType;

        // ИНИЦИАЛИЗАЦИЯ ДАТ
        displayDateFrom = null;
        displayDateTo = null;
        syncPwrProjectGlobals();
        projectDates = null;

        // Сбрасываем ссылки на контролы
        dateFromControl = null;
        dateToControl = null;

        // ВАЖНО: СБРАСЫВАЕМ ФЛАГ ТАБЛИЦЫ
        frm.project_workload_table_initialized = false;
        // Также удаляем свойство dt, если оно есть
        if (frm.project_workload_dt) {
            frm.project_workload_dt = null;
        }

        if (WL_DEBUG) console.log("Dates will be initialized when needed, table flag reset to false");

        // Применяем стили
        if (typeof applyProjectWorkloadStyle === 'function') {
            applyProjectWorkloadStyle();
        }
    },

    refresh: function(frm) {
        if (WL_DEBUG) console.log("Project Workload: refresh");
        // При обновлении страницы тоже сбрасываем
        frm.project_workload_table_initialized = false;
        if (frm.project_workload_dt) {
            frm.project_workload_dt = null;
        }
        render_project_workload_table(frm);
    },

    before_save: function(frm) {
        // Сохраняем текущие даты в документе для восстановления при перезагрузке
        if (displayDateFrom && displayDateTo) {
            frm.doc.custom_workload_date_from = displayDateFrom;
            frm.doc.custom_workload_date_to = displayDateTo;
        }
    }
});

window.debouncedLoadProjectWorkloadData = debouncedLoadProjectWorkloadData;

$(document).on("pwr-workload-data-reload", function (_event, frm, meta) {
    if (!frm || frm.doctype !== "Project") {
        return;
    }
    if (meta && typeof meta.showFact === "boolean") {
        window.pwrShowFact = meta.showFact;
    }
    if (meta && meta.periodAnchor && typeof displayDateFrom !== "undefined") {
        displayDateFrom = meta.periodAnchor;
        window.displayDateFrom = displayDateFrom;
        syncPwrProjectGlobals();
    }
    debouncedLoadProjectWorkloadData(frm, true, true);
});

/**
 * Выполняет проверку перегрузки
 */
function perform_overload_check(frm) {
    /*frappe.show_alert({
        message: __("Выполняется проверка перегрузки..."),
        indicator: 'orange'
    }, 10);/**/
    
    let periods = get_display_periods(frm, "month");
    
    frappe.call({
        method: "check_workload_overload",
        args: {
            project: frm.doc.name,
            periods: periods,
            view_options: frm.view_options  // ← передается из селектора
        },
        freeze: true,
        freeze_message: __("Проверка загрузки и трудозатрат по проекту..."),
        callback: function(r) {
            if (r.message && r.message.overloads) {
                let overloads = r.message.overloads;
                
                if (overloads.length === 0) {
                    frappe.show_alert({
                        message: __("Расхождений не обнаружено"),
                        indicator: 'green'
                    }, 3);
                    return;
                }
                
                // Сохраняем данные о перегрузках в frm для подсветки аватаров
                frm._overloadMap = {};
                
                overloads.forEach(overload => {
                    // Для каждого месяца в детализации собираем информацию о пользователях
                    if (overload.months) {
                        overload.months.forEach(month => {
                            month.users.forEach(user => {
                                let key = `${overload.task}_${overload.role}_${user.user}`;
                                if (!frm._overloadMap[key]) {
                                    frm._overloadMap[key] = [];
                                }
                                frm._overloadMap[key].push({
                                    year: month.year,
                                    month: month.month,
                                    forecast_hours: month.forecast_hours,
                                    assigned_hours: user.assigned,
                                    overload_hours: user.assigned - month.forecast_hours
                                });
                            });
                        });
                    }
                });
                
                // Обновляем таблицу для отображения подсветки аватаров
                //updateTable(frm, "month", "hours");
                
                // Показываем сообщение с количеством проблем
                /*frappe.show_alert({
                    message: __("Найдено {0} случаев перегрузки по задачам и ролям", [overloads.length]),
                    indicator: 'orange'
                }, 5);/**/
                
                // Показываем детальный диалог с возможностью выбора строк
                show_overload_details_dialog(overloads, frm);
            } else if (r.message && r.message.error) {
                console.error("Server error:", r.message.error);
                frappe.msgprint(__("Ошибка при проверке: {0}", [r.message.error]));
            } else {
                console.error("Unexpected response structure:", r);
                frappe.msgprint(__("Неожиданный ответ от сервера"));
            }
        },
        error: function(err) {
            console.error("AJAX Error:", err);
            frappe.msgprint(__("Ошибка при проверке расхождений загрузки"));
        }
    });
}

/**
 * Показывает диалог с деталями перегрузок используя StickyDataTable
 */
function show_overload_details_dialog(overloads, frm) {
    if (!overloads || overloads.length === 0) return;
    
    // Создаем карту перегрузок: task -> { role: overloadData }
    let overloadMap = {};
    overloads.forEach(overload => {
        if (!overloadMap[overload.task]) {
            overloadMap[overload.task] = {};
        }
        overloadMap[overload.task][overload.role] = overload;
    });
    
    // Получаем все задачи проекта
    let allTasks = frm.aggregatedTasks ? Object.values(frm.aggregatedTasks) : [];
    
    // Находим задачи с перегрузкой и их родителей
    let tasksWithOverload = new Set();
    allTasks.forEach(task => {
        if (overloadMap[task.value]) {
            tasksWithOverload.add(task.value);
        }
    });
    
    let tasksToShow = new Set(tasksWithOverload);
    tasksWithOverload.forEach(taskId => {
        let current = allTasks.find(t => t.value === taskId);
        while (current && current.parent_task) {
            tasksToShow.add(current.parent_task);
            current = allTasks.find(t => t.value === current.parent_task);
        }
    });
    
    // Строим данные
    let table_data = [];
    
    allTasks.forEach(task => {
        if (tasksToShow.has(task.value)) {
            let taskCopy = JSON.parse(JSON.stringify(task));
            
            let new_role_data = [];
            let rolesData = overloadMap[task.value] || {};
            
            if (Object.keys(rolesData).length > 0) {
                Object.keys(rolesData).forEach(role => {
                    let roleEntry = taskCopy.role_data?.find(r => r.role === role);
                    if (roleEntry) {
                        // Добавляем данные о перегрузке в roleEntry
                        let overload = rolesData[role];
                        roleEntry.total_forecast = overload.total_forecast;
                        roleEntry.total_assigned = overload.total_assigned;
                        roleEntry.overload = overload.overload;
                        new_role_data.push(roleEntry);
                    } else {
                        new_role_data.push({ 
                            role: role,
                            total_forecast: rolesData[role].total_forecast,
                            total_assigned: rolesData[role].total_assigned,
                            overload: rolesData[role].overload
                        });
                    }
                });
                taskCopy.role_data = new_role_data;
                taskCopy.has_overload = true;
            } else {
                taskCopy.role_data = [];
                taskCopy.has_overload = false;
            }
            
            table_data.push(taskCopy);
        }
    });
    
    // Рассчитываем высоту
    let tableHeight = Math.min(500, Math.max(200, table_data.length * 30 + 40));
    
    // Создаем диалог
    let dialog = new frappe.ui.Dialog({
        title: __("Расхождения прогноза трудозатрат и назначенной загрузки"),
        size: "large",
        fields: [
            {
                fieldtype: "HTML",
                fieldname: "table_container",
                options: `<div class="overload-table-container" style="height: ${tableHeight}px; width: 100%; overflow: auto;"></div>`
            },
            {
                fieldtype: "HTML",
                fieldname: "info_html",
                options: `
                    <div class="text-muted" style="margin-top: 10px; padding: 8px 10px; background: var(--bg-light-gray); border-radius: 4px; font-size: 12px;">
                        <i class="fa fa-info-circle" style="margin-right: 5px;"></i>
                        <strong>${__("Отметьте галочками задачи и роли для обновления прогноза")}</strong>
                    </div>
                `
            }
        ],
        primary_action_label: __("Обновить трудозатраты"),
        primary_action: function(values) {
            let checkedRows = dialog.datatable.rowmanager.getCheckedRows();
            
            if (!checkedRows || checkedRows.length === 0) {
                frappe.msgprint(__("Выберите хотя бы одну задачу и роль"));
                return;
            }
            
            let selected_rows = [];
            
            checkedRows.forEach(rowIndex => {
                let rowData = dialog.datatable.datamanager.getData(rowIndex);
                if (rowData && rowData.role_data && rowData.role_data.length > 0) {
                    rowData.role_data.forEach(roleEntry => {
                        let role = roleEntry.role;
                        let overloadData = overloadMap[rowData.value]?.[role];
                        if (overloadData) {
                            selected_rows.push({
                                task: rowData.value,
                                role: role,
                                months: overloadData.months
                            });
                        }
                    });
                }
            });
            
            if (selected_rows.length === 0) {
                frappe.msgprint(__("Выберите хотя бы одну задачу и роль с перегрузкой"));
                return;
            }
            
            frappe.confirm(
                __("Обновить прогноз для {0} позиций?", [selected_rows.length]),
                () => update_forecast_from_assignments(frm, selected_rows, dialog)
            );
        },
        secondary_action_label: __("Закрыть"),
        secondary_action: function() {
            dialog.hide();
        }
    });
    
    dialog.show();
    
    // Создаем таблицу с задержкой
    setTimeout(() => {
        let container = dialog.$wrapper.find('.overload-table-container');
        
        let columns = [
            {
                name: __("Задача"),
                id: "subject",
                width: 200,
                treeView: true,
                sortable: false,
                format: (value) => value || ''
            },
            {
                name: __("Роль"),
                id: "role",
                width: 120,
                sortable: false,
                format: (value, row, column, data) => {
                    if (data && data.role_data && data.role_data.length > 0) {
                        return data.role_data.map(r => r.role || '—').join('<br>');
                    }
                    return '—';
                }
            },
            {
                name: __("Трудозатраты"),
                id: "total_forecast",
                width: 110, // Увеличено с 80 (примерно на треть)
                sortable: false,
                format: (value, row, column, data) => {
                    if (data && data.role_data && data.role_data.length > 0) {
                        return data.role_data.map(r => {
                            if (r.total_forecast !== undefined) {
                                return r.total_forecast.toFixed(1);
                            }
                            return '—';
                        }).join('<br>');
                    }
                    return '—';
                }
            },
            {
                name: __("Загрузка"),
                id: "total_assigned",
                width: 110, // Увеличено с 80
                sortable: false,
                format: (value, row, column, data) => {
                    if (data && data.role_data && data.role_data.length > 0) {
                        return data.role_data.map(r => {
                            if (r.total_assigned !== undefined) {
                                return `<span style="color: #e67e22;">${r.total_assigned.toFixed(1)}</span>`;
                            }
                            return '—';
                        }).join('<br>');
                    }
                    return '—';
                }
            },
            {
                name: __("Расхождение"),
                id: "overload",
                width: 110, // Увеличено с 80
                sortable: false,
                format: (value, row, column, data) => {
                    if (data && data.role_data && data.role_data.length > 0) {
                        return data.role_data.map(r => {
                            if (r.overload !== undefined) {
                                return `<span style="color: #e74c3c; font-weight: bold;">${r.overload.toFixed(1)}</span>`;
                            }
                            return '—';
                        }).join('<br>');
                    }
                    return '—';
                }
            }
        ];
        
        // Создаем таблицу
        dialog.datatable = new StickyDataTable(container[0], {
            columns: columns,
            data: table_data,
            treeView: true,
            checkboxColumn: true,
            checkedRowStatus: false,
            layout: "fixed",
            inlineFilters: false,
            disableReorderColumn: true,
            serialNoColumn: true,
            cellHeight: 30
        });
        
        // Скрываем чекбоксы для строк без перегрузки
        setTimeout(() => {
            container.find('.dt-row').each(function() {
                let rowIndex = $(this).data('row-index');
                if (rowIndex !== undefined && dialog.datatable.datamanager) {
                    let rowData = dialog.datatable.datamanager.getData(rowIndex);
                    
                    if (rowData && !rowData.has_overload) {
                        // Скрываем чекбокс для родительских задач без перегрузки
                        $(this).find('.dt-cell--col-0 input[type="checkbox"]').hide();
                        // Добавляем серый фон
                        $(this).css('background-color', '#f8f9fa');
                    }
                }
            });
        }, 100);
        
    }, 200);
}

function escape_html(str) {
    if (!str) return '';
    return String(str).replace(/[&<>]/g, function(m) {
        if (m === '&') return '&amp;';
        if (m === '<') return '&lt;';
        if (m === '>') return '&gt;';
        return m;
    });
}

/**
 * Обновляет прогнозные данные на основе назначений
 */
function update_forecast_from_assignments(frm, selectedRows, dialog) {
    let updates = [];
    
    selectedRows.forEach(row => {
        let task = row.task;
        let role = row.role;
        let months = row.months;
        
        months.forEach(month => {
            updates.push({
                task: task,
                role: role,
                year: month.year,
                month: month.month,
                assigned_hours: month.assigned_hours
            });
        });
    });
    
    let updates_json = JSON.stringify(updates);
    
    frappe.call({
        method: "update_forecast_from_assignments",
        args: {
            project: frm.doc.name,
            updates_json: updates_json
        },
        freeze: true,
        freeze_message: __("Обновление прогнозных трудозатрат..."),
        callback: function(r) {
            if (r.message && r.message.success) {
                frappe.show_alert({
                    message: __("Прогнозные данные успешно обновлены для {0} позиций", [r.message.updated_count]),
                    indicator: 'green'
                }, 5);
                
                if (dialog) dialog.hide();
                
                // Очищаем кэши
                clear_assignments_cache();
                clearTaskIndexCacheFor(frm.aggregatedTasks);
                frm.last_loaded_time = null;
                frm.last_loaded_project = null;
                frm._overloadMap = {};
                frm._missingPlanMap = {};
                
                // Перезагружаем таблицу
                load_work_efforts_data(frm, "month", "hours", true);
                
                /*frappe.show_alert({
                    message: __("Данные обновлены. Для просмотра новых перегрузок выполните проверку еще раз."),
                    indicator: 'blue'
                }, 5);/**/
            } else if (r.message && r.message.error) {
                frappe.msgprint(__("Ошибка при обновлении: {0}", [r.message.error]));
            } else {
                frappe.msgprint(__("Неизвестная ошибка при обновлении прогнозных данных"));
            }
        },
        error: function(err) {
            console.error("AJAX Error:", err);
            frappe.msgprint(__("Ошибка при обновлении прогнозных данных"));
        }
    });
}

