    console.log('Opening user absence for:', userEmail, 'on date:', dateStr);
    
    try {
        const absences = await frappe.db.get_list('Application For Leave', {
            fields: ['name', 'alfrom_date', 'alto_date'],
            filters: [
                ['lauser', '=', userEmail],
                ['status', '=', 'Согласовано'],
                ['alfrom_date', '<=', dateStr],
                ['alto_date', '>=', dateStr]
