        const result = await frappe.call({
            method: 'get_projects_workload_data',
            args: {
                user: frm.doc.user || '',
                project: frm.doc.project || '',
                user_group: frm.doc.user_group || '',
                view_type: currentViewType,
                period_range: currentPeriodRange
            },
            freeze: true,
            freeze_message: __('Получение данных загрузки проектов...')
        });
        
        console.timeEnd("get_projects_workload_data");
        console.log('Full server response:', result);
        
        if (!result) {
            throw new Error(__('Нет ответа от сервера'));
        }
        
        if (!result.message) {
            throw new Error(__('Пустой ответ от сервера'));
        }
        
        if (result.message.error) {
