            periods_length: periods ? periods.length : 0,
            users_count,
            projects_count,
            assignments_count,
            message
        });

        if (periods && periods.length > 0) {
            console.log('=== PERIODS DEBUG ===');
            console.log('First period:', periods[0]);
            console.log('Last period:', periods[periods.length - 1]);
            
            if (currentViewType === 'daily') {
                console.log('Daily periods range:', periods[0].date, 'to', periods[periods.length - 1].date);
            } else if (currentViewType === 'weekly') {
                console.log('Weekly periods range:', periods[0].start_date, 'to', periods[periods.length - 1].end_date);
            } else {
                console.log('Monthly periods range:', periods[0].start_date, 'to', periods[periods.length - 1].end_date);
            }
        }

        if (currentViewType === 'weekly' && tree_data && tree_data.length > 0) {
            console.log('=== WEEKLY DATA DEBUG ===');
            console.log('First row data:', tree_data[0]);
            console.log('Server periods:', periods);
            
            const weeklyKeys = Object.keys(tree_data[0]).filter(key => key.startsWith('workload_'));
